    bg: "innodb_flush_method=O_DIRECT не е подходящ за macOS. Използвайте метода по подразбиране локално или тествайте на Linux.",
    zh: "innodb_flush_method=O_DIRECT 不适合 macOS。本地请使用默认刷新方式，或在 Linux 上测试。",
    hr: "innodb_flush_method=O_DIRECT nije prikladan na macOS-u. Lokalno koristite zadanu metodu ili testirajte na Linuxu.",
    cs: "innodb_flush_method=O_DIRECT není vhodné na macOS. Lokálně použijte výchozí metodu nebo testujte na Linuxu.",
    nl: "innodb_flush_method=O_DIRECT is niet geschikt op macOS. Gebruik lokaal de standaardmethode of test op Linux.",
    en: "innodb_flush_method=O_DIRECT is not appropriate on macOS. Use the default flush method locally or test on Linux.",
    et: "innodb_flush_method=O_DIRECT ei sobi macOS-ile. Kasutage kohalikult vaikemeetodit või testige Linuxis.",
    fi: "innodb_flush_method=O_DIRECT ei sovi macOS:lle. Käytä paikallisesti oletusmenetelmää tai testaa Linuxissa.",
    fr: "innodb_flush_method=O_DIRECT ne convient pas à macOS. Utilisez la méthode par défaut en local ou testez sous Linux.",
    de: "innodb_flush_method=O_DIRECT ist auf macOS ungeeignet. Lokal die Standardmethode nutzen oder unter Linux testen.",
    el: "Το innodb_flush_method=O_DIRECT δεν είναι κατάλληλο στο macOS. Χρησιμοποιήστε την προεπιλογή τοπικά ή δοκιμάστε σε Linux.",
    he: "innodb_flush_method=O_DIRECT אינו מתאים ל-macOS. השתמשו בשיטת ברירת המחדל מקומית או בדקו ב-Linux.",
    hi: "innodb_flush_method=O_DIRECT macOS पर उपयुक्त नहीं है। स्थानीय रूप से डिफ़ॉल्ट विधि उपयोग करें या Linux पर जाँचें।",
    hu: "Az innodb_flush_method=O_DIRECT nem megfelelő macOS-en. Helyben az alapértelmezett módszert használja, vagy Linuxon teszteljen.",
    id: "innodb_flush_method=O_DIRECT tidak cocok di macOS. Pakai metode default secara lokal atau uji di Linux.",
