    ja: "innodb_flush_method=O_DIRECT は macOS 向きではありません。ローカルでは既定の flush 方法を使うか、Linux で検証してください。",
    jv: "innodb_flush_method=O_DIRECT ora cocog ing macOS. Gunakake metode default lokal utawa uji ing Linux.",
    ko: "innodb_flush_method=O_DIRECT는 macOS에 맞지 않습니다. 로컬에서는 기본 flush 방법을 쓰거나 Linux에서 테스트하세요.",
    mr: "innodb_flush_method=O_DIRECT macOS वर योग्य नाही. स्थानिकपणे डीफॉल्ट पद्धत वापरा किंवा Linux वर तपासा.",
