    es: "innodb_flush_method=O_DIRECT no es adecuado en macOS. Use el método predeterminado en local o pruebe en Linux.",
    sv: "innodb_flush_method=O_DIRECT passar inte på macOS. Använd standardmetoden lokalt eller testa på Linux.",
    ta: "innodb_flush_method=O_DIRECT macOS-இல் பொருந்தாது. உள்ளூரில் இயல்புநிலை முறையைப் பயன்படுத்தவும் அல்லது Linux-இல் சோதிக்கவும்.",
