    bn: "বড় buffer pool-কে ইনস্ট্যান্সে ভাগ করে মাল্টিকোর হোস্টে latch প্রতিযোগিতা কমায়।",
    bg: "Разделя голям buffer pool на инстанции, за да намали конкуренцията за latch на многоядрени хостове.",
