    cs: "Rozděluje velký buffer pool na instance, aby snížil soupeření o latch na vícejádrových hostitelích.",
    nl: "Splitst een grote buffer pool in instanties om latch-concurrentie op multi-core hosts te verminderen.",
    en: "Splits a large buffer pool into instances to reduce latch contention on multi-core hosts.",
