    fr: "Découpe un grand buffer pool en instances pour réduire la contention sur les latch des hôtes multi-cœurs.",
    de: "Teilt einen großen Buffer Pool in Instanzen, um Latch-Konkurrenz auf Mehrkern-Hosts zu senken.",
    el: "Χωρίζει ένα μεγάλο buffer pool σε instances για να μειώσει τον ανταγωνισμό latch σε πολυπύρηνους hosts.",
    he: "מפצל buffer pool גדול למופעים כדי להפחית תחרות latch במארחים מרובי ליבות.",
    hi: "बड़े buffer pool को इंस्टेंस में बाँटता है ताकि मल्टी-कोर होस्ट पर latch प्रतिस्पर्धा कम हो।",
    hu: "Nagy buffer poolt példányokra oszt, hogy csökkentse a latch-versenyt többmagos gazdákon.",
    id: "Memecah buffer pool besar menjadi instance agar mengurangi persaingan latch di host multi-inti.",
    it: "Divide un grande buffer pool in istanze per ridurre la contesa sui latch su host multi-core.",
