    pt: "Divide um buffer pool grande em instâncias para reduzir contenção de latch em hosts multi-core.",
    pa: "ਵੱਡੇ buffer pool ਨੂੰ ਇੰਸਟੈਂਸਾਂ ਵਿੱਚ ਵੰਡਦਾ ਹੈ ਤਾਂ ਜੋ ਮਲਟੀ-ਕੋਰ ਹੋਸਟ ਉੱਤੇ latch ਮੁਕਾਬਲਾ ਘਟੇ।",
    ro: "Împarte un buffer pool mare în instanțe pentru a reduce concurența pe latch pe host-uri multi-core.",
    ru: "Делит большой buffer pool на инстансы, чтобы снизить конкуренцию за latch на многоядерных хостах.",
