    sv: "Delar en stor buffer pool i instanser för att minska latch-konkurrens på flerkärniga värdar.",
    ta: "பெரிய buffer pool-ஐ நிகழ்வுகளாகப் பிரித்து பல கோர் ஹோஸ்ட்களில் latch போட்டியைக் குறைக்கிறது.",
