    en: "Threads that purge undo history. Raise on write-heavy OLTP when history length grows.",
    et: "Lõimed, mis puhastavad undo-ajalugu (purge). Suurenda kirjutusmahukal OLTP-l, kui ajaloo pikkus kasvab.",
