    fr: "Threads qui purgent l’historique undo. À augmenter en OLTP intensif en écriture lorsque la longueur de l’historique croît.",
    de: "Threads, die die Undo-Historie bereinigen (Purge). Bei schreiblastigem OLTP erhöhen, wenn die History-Länge wächst.",
