    bn: "ডিস্কে স্পিল হওয়ার আগে ইন-মেমরি অভ্যন্তরীণ টেম্প টেবিলের সর্বোচ্চ আকার। max_heap_table_size-এর সঙ্গে সামঞ্জস্য রাখুন।",
