    pt: "Mantém threads inativas em cache para evitar a criação e destruição constantes em cargas com muitas ligações.",
    pa: "ਵਿਹਲੇ ਥ੍ਰੈਡਾਂ ਨੂੰ ਕੈਸ਼ ਕਰਦਾ ਹੈ ਤਾਂ ਜੋ ਕਨੈਕਸ਼ਨ-ਭਾਰੀ ਲੋਡ ਵਿੱਚ ਵਾਰ-ਵਾਰ ਬਣਾਉਣ/ਨਸ਼ਟ ਕਰਨ ਦੀ ਲਾਗਤ ਤੋਂ ਬਚਿਆ ਜਾ ਸਕੇ।",
