    ta: "செயலற்ற த்ரெட்களை கேஷ் செய்கிறது; இணைப்பு அதிகமான சுமைகளில் மீண்டும் மீண்டும் உருவாக்கி அழிக்கும் செலவைத் தவிர்க்கிறது.",
