    hu: "A MyISAM kulcsgyorsítótára. Csak InnoDB-t használó szervereken tartsa kicsin; csak akkor emelje, ha a MyISAM/rendszertáblák számítanak.",
    id: "Key cache MyISAM. Jaga tetap kecil pada server hanya InnoDB; naikkan hanya jika MyISAM/tabel sistem berperan.",
    it: "Key cache di MyISAM. Mantienila piccola sui server solo InnoDB; aumentala solo se MyISAM/le tabelle di sistema contano.",
