    ta: "MyISAM விசை கேஷ். InnoDB மட்டும் உள்ள சேவையகங்களில் சிறியதாக வைக்கவும்; MyISAM/கணினி அட்டவணைகள் முக்கியமெனில் மட்டும் உயர்த்துங்கள்.",
    te: "MyISAM కీ కాష్. InnoDB మాత్రమే ఉన్న సర్వర్‌లలో చిన్నగా ఉంచండి; MyISAM/సిస్టమ్ టేబుల్‌లు ముఖ్యమైతేనే పెంచండి.",
