    el: "Πόσο συχνά γίνεται fsync στο δυαδικό αρχείο καταγραφής. Το 1 είναι το ασφαλέστερο για τη διάρκεια της αντιγραφής· το 0 είναι ταχύτερο αλλά πιο επικίνδυνο.",
    he: "באיזו תדירות מבוצע fsync ליומן הבינארי. 1 הוא הבטוח ביותר לעמידות הרפליקציה; 0 מהיר יותר אך מסוכן יותר.",
    hi: "बाइनरी लॉग का fsync कितनी बार होता है। रेप्लिकेशन टिकाऊपन के लिए 1 सबसे सुरक्षित है; 0 तेज़ है पर जोखिम भरा।",
    hu: "Milyen gyakran fsync-eli a bináris naplót. Az 1 a legbiztonságosabb a replikáció tartóssága szempontjából; a 0 gyorsabb, de kockázatosabb.",
    id: "Seberapa sering binary log di-fsync. 1 paling aman untuk ketahanan replikasi; 0 lebih cepat tetapi lebih berisiko.",
