    ta: "பைனரி பதிவு எவ்வளவு அடிக்கடி fsync செய்யப்படுகிறது. பிரதியெடுப்பின் நிலைத்தன்மைக்கு 1 பாதுகாப்பானது; 0 வேகமானது ஆனால் ஆபத்தானது.",
    te: "బైనరీ లాగ్‌కు ఎంత తరచుగా fsync జరుగుతుంది. రెప్లికేషన్ మన్నికకు 1 అత్యంత సురక్షితం; 0 వేగవంతం కానీ ప్రమాదకరం.",
    tr: "İkili günlüğün ne sıklıkla fsync edildiği. Replikasyon dayanıklılığı için 1 en güvenlisidir; 0 daha hızlıdır ama daha risklidir.",
    uk: "Як часто виконується fsync двійкового журналу. 1 — найбезпечніше для надійності реплікації; 0 швидше, але ризикованіше.",
