    bn: "RAM/CPU/ডিস্ক ও MySQL RAM অংশ পূরণ করে; ফলাফল অংশে managed প্ল্যাটফর্ম এখনও বদলাতে পারবেন।",
    bg: "Попълва RAM/CPU/диск и дела RAM за PG; управлявана платформа пак можете да смените в раздела с резултата.",
