    he: "ממלאת RAM/מעבד/דיסק ואת נתח ה-RAM של PG; את הפלטפורמה המנוהלת עדיין אפשר לשנות בחלק התוצאה.",
    hi: "RAM/CPU/डिस्क और MySQL RAM हिस्सा भरता है; परिणाम खंड में managed प्लेटफ़ॉर्म फिर भी बदल सकते हैं।",
    hu: "Kitölti a RAM-ot/CPU-t/lemezt és a MySQL RAM-arányát; a kezelt platformot az eredmény szekcióban továbbra is módosíthatja.",
