    it: "Compila RAM/CPU/disco e la quota RAM PG; puoi comunque cambiare la piattaforma managed nella sezione risultato.",
    ja: "RAM/CPU/ディスクと MySQL の RAM 配分を入力します。結果欄で managed プラットフォームは引き続き変更できます。",
    jv: "Ngisi RAM/CPU/disk lan porsi RAM PG; platform managed isih bisa diganti ing bagean asil.",
    ko: "RAM/CPU/디스크와 MySQL RAM 비중을 채웁니다. 결과 영역에서 managed 플랫폼은 여전히 바꿀 수 있습니다.",
    mr: "RAM/CPU/डिस्क आणि MySQL RAM वाटा भरतो; निकाल विभागात managed प्लॅटफॉर्म अजून बदलता येतो.",
    no: "Fyller ut RAM/CPU/disk og PG-RAM-andel; du kan fortsatt bytte administrert plattform i resultatdelen.",
    fa: "RAM/CPU/دیسک و سهم RAM مربوط به MySQL را پر می‌کند؛ هنوز می‌توانید پلتفرم managed را در بخش نتیجه عوض کنید.",
    pl: "Wypełnia RAM/CPU/dysk i udział RAM dla PG; platformę zarządzaną nadal można zmienić w sekcji wyniku.",
    pt: "Preenche RAM/CPU/disco e a parcela de RAM do PG; ainda pode mudar a plataforma managed na seção de resultado.",
    pa: "RAM/CPU/ਡਿਸਕ ਅਤੇ MySQL RAM ਹਿੱਸਾ ਭਰਦਾ ਹੈ; ਨਤੀਜਾ ਭਾਗ ਵਿੱਚ managed ਪਲੇਟਫਾਰਮ ਫਿਰ ਵੀ ਬਦਲ ਸਕਦੇ ਹੋ।",
    ro: "Completează RAM/CPU/disc și cota de RAM pentru PG; platforma gestionată o puteți schimba în continuare în secțiunea de rezultat.",
    ru: "Подставит RAM/CPU/диск и долю под PG; платформу managed можно сменить в блоке результата.",
    es: "Rellena RAM/CPU/disco y la porción de RAM de PG; aún puede cambiar la plataforma managed en la sección de resultado.",
