    ta: "RAM/CPU/வட்டு மற்றும் MySQL RAM பங்கை நிரப்புகிறது; முடிவு பகுதியில் managed தளத்தை இன்னும் மாற்றலாம்.",
    te: "RAM/CPU/డిస్క్ మరియు MySQL RAM వాటాను నింపుతుంది; ఫలిత విభాగంలో managed ప్లాట్‌ఫామ్‌ను ఇంకా మార్చవచ్చు.",
    tr: "RAM/CPU/disk ve MySQL RAM payını doldurur; sonuç bölümünde managed platformu yine değiştirebilirsiniz.",
    uk: "Заповнює RAM/CPU/диск і частку RAM для PG; керовану платформу все ще можна змінити в розділі результату.",
