    fi: "Istunnot {backends}/{max}: yhteyspainetta — harkitse pooleria tai max_connections-arvon varovaista nostoa.",
    fr: "{backends} connexions sur {max} sont utilisées : c’est beaucoup, le nombre de connexions est donc relevé avec de la marge. Envisagez un pooler comme ProxySQL.",
    de: "{backends} von {max} Verbindungen sind belegt: Das ist viel, daher wird die Verbindungszahl mit Puffer erhöht. Erwägen Sie einen Pooler wie ProxySQL.",
    el: "Συνεδρίες {backends}/{max}: πίεση συνδέσεων — εξετάστε pooler ή προσεκτική αύξηση του max_connections.",
